import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.OnScreenTextureAnimation{AnimationType: 0xdeadbeef}
ANIMATION = bytes.fromhex("efbeadde")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.OnScreenTextureAnimation{AnimationType: 1}
ONE = bytes.fromhex("01000000")

GOLDENS = [
    pytest.param(
        v.OnScreenTextureAnimationPacket(effect_id=0xDEADBEEF),
        ANIMATION,
        id=f"{v.__name__.rpartition('.')[2]}-animation",
    )
    for v in VERSIONS
] + [
    pytest.param(
        v.OnScreenTextureAnimationPacket(effect_id=1), ONE, id=f"{v.__name__.rpartition('.')[2]}-fixed-four-byte-field"
    )
    for v in VERSIONS
]


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_on_screen_texture_animation_is_packet_130(version):
    assert version.PACKETS[130] is version.OnScreenTextureAnimationPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_on_screen_texture_animation_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_on_screen_texture_animation_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_on_screen_texture_animation_rejects_a_short_body(version):
    with pytest.raises(ValueError, match="at byte"):
        version.OnScreenTextureAnimationPacket.from_bytes(ANIMATION[:3])
